const fs=require('fs'),path=require('path'),http=require('http'),cp=require('child_process'),{chromium}=require('playwright');
const root=process.cwd(),file='cursor-test/urasoe.html',out='qa-urasoe-preview-20261119';fs.mkdirSync(out,{recursive:true});
const before=cp.execFileSync('git',['show','origin/main:'+file],{encoding:'utf8'}),after=fs.readFileSync(file,'utf8'),assert=(v,m)=>{if(!v)throw Error(m)};
const attrs=(z,re)=>[...z.matchAll(re)].map(x=>x[1]||x[0]);const prices=z=>new Set(attrs(z,/[\d,]+円(?:〜|～)?/g));const links=z=>attrs(z,/\bhref="([^"]+)"/g);for(const x of links(before))assert(links(after).includes(x),'old link removed: '+x);for(const x of prices(before))assert(prices(after).has(x),'old price removed: '+x);
const scripts=z=>[...z.matchAll(/<script\b(?![^>]*type="application\/ld\+json")[\s\S]*?<\/script>/g)].map(x=>x[0]);assert(JSON.stringify(scripts(before))===JSON.stringify(scripts(after)),'JS/GA4 changed');
const data=[...after.matchAll(/<script type="application\/ld\+json">([\s\S]*?)<\/script>/g)].map(x=>JSON.parse(x[1]));const faq=data.find(x=>x['@type']==='FAQPage');assert(faq&&faq.mainEntity.length===5,'FAQ schema 5');
const src=cp.execFileSync('git',['show','origin/main:complete-disassembly/index.html'],{encoding:'utf8'});assert(src.includes('匿名カズさん・2026年4月22日')&&src.includes('3台、完全分解を依頼しました。'),'review source');
assert(!after.includes('カビの再発防止')&&!after.includes('汚れの原因まで徹底洗浄'),'cleanup claims');
const types={'.html':'text/html; charset=utf-8','.css':'text/css; charset=utf-8','.js':'text/javascript','.jpg':'image/jpeg','.jpeg':'image/jpeg','.png':'image/png','.webp':'image/webp','.svg':'image/svg+xml','.ico':'image/x-icon'};
function serve(phase,port){return new Promise((resolve,reject)=>{const srv=http.createServer((req,res)=>{let p=decodeURIComponent(new URL(req.url,'http://127.0.0.1').pathname);if(p==='/cursor-test/urasoe.html'){res.writeHead(200,{'Content-Type':types['.html']});return res.end(phase?after:before)}const name=path.resolve(root,'.'+(p.endsWith('/')?p+'index.html':p));if(!name.startsWith(root+path.sep)){res.writeHead(403);return res.end()};fs.readFile(name,(e,b)=>{if(e){res.writeHead(404);return res.end()};res.writeHead(200,{'Content-Type':types[path.extname(name)]||'application/octet-stream'});res.end(b)})});srv.listen(port,'127.0.0.1',()=>resolve(srv)).on('error',reject)})}
async function check(browser,phase,port,width){const ctx=await browser.newContext({viewport:{width,height:900},deviceScaleFactor:1,reducedMotion:'reduce'}),page=await ctx.newPage(),errors=[],bad=[];
page.on('pageerror',e=>errors.push(e.message));page.on('response',r=>{if(r.url().startsWith('http://127.0.0.1:'+port+'/')&&r.status()>=400)bad.push(r.status()+' '+r.url())});await page.route('**/*',r=>r.request().url().startsWith('http://127.0.0.1:'+port+'/')?r.continue():r.abort('blockedbyclient'));
const resp=await page.goto('http://127.0.0.1:'+port+'/cursor-test/urasoe.html',{waitUntil:'domcontentloaded',timeout:45000});
await page.locator('img').evaluateAll(els=>els.forEach(e=>e.loading='eager'));await page.evaluate(async()=>{await Promise.all([...document.images].map(x=>x.decode().catch(()=>{})));for(let y=0;y<document.documentElement.scrollHeight;y+=860){scrollTo(0,y);await new Promise(r=>setTimeout(r,8))}scrollTo(0,0)});
const x=await page.evaluate(()=>{const grid=document.querySelector('.urasoe-conditions'),g=grid?getComputedStyle(grid):null,first=document.querySelector('h1 span'),firstStyle=first?getComputedStyle(first):null;return {w:innerWidth,scroll:document.documentElement.scrollWidth,height:document.documentElement.scrollHeight,hero:document.querySelector('.hero-inner')?.innerText||'',title:document.querySelector('h1')?.innerText||'',firstHeight:first?.getBoundingClientRect().height||0,firstLine:parseFloat(firstStyle?.lineHeight)||0,gridItems:grid?.querySelectorAll('.reason-item').length||0,cols:g?.gridTemplateColumns?.split(' ').length||0,
images:[...document.images].map(x=>({src:x.getAttribute('src'),ok:x.complete&&x.naturalWidth>0})),faq:document.querySelectorAll('#faq details.faq-details').length,LINE:[...document.querySelectorAll('a[href*="lin.ee"]')].map(x=>x.getAttribute('href')),tel:[...document.querySelectorAll('a[href^="tel:"]')].map(x=>x.getAttribute('href')),reserve:[...document.querySelectorAll('a[href*="airrsv.net"]')].map(x=>x.getAttribute('href')),quote:document.querySelectorAll('.urasoe-verified-voice').length,source:!!document.querySelector('.urasoe-source-link[href="../complete-disassembly/"]'),schema:document.querySelectorAll('script[type="application/ld+json"]').length,tracking:!!document.querySelector('script[src*="gtag/js?id=G-X8LKLFDL3G"]'),text:document.body.textContent||'',
overflow:[...document.querySelectorAll('h1,h2,h3,h4,p,a,summary')].filter(e=>e.getClientRects().length&&!e.closest('.header-nav')).map(e=>({txt:(e.textContent||'').slice(0,24),rect:e.getBoundingClientRect()})).filter(z=>z.rect.width>0&&(z.rect.left < -6||z.rect.right>innerWidth+6)).slice(0,8)}});
await page.screenshot({path:path.join(out,(phase?'after':'before')+'-'+width+'.png'),fullPage:true,animations:'disabled',timeout:60000});
if(phase){const qs=page.locator('#faq details.faq-details');for(let i=0;i<await qs.count();i++){const q=qs.nth(i),open=await q.evaluate(e=>e.open);await q.locator('summary').click();assert((await q.evaluate(e=>e.open))!==open,'FAQ click '+i);await q.locator('summary').click();assert((await q.evaluate(e=>e.open))===open,'FAQ reset '+i)}}await ctx.close();return{http:resp.status(),...x,errors,bad}};
(async()=>{let oldS,newS,b;try{oldS=await serve(0,8771);newS=await serve(1,8772);b=await chromium.launch({channel:'chrome',headless:true});let results=[];
for(const width of [1440,390,320]){const x=await check(b,0,8771,width),y=await check(b,1,8772,width);
assert(x.http===200&&y.http===200,'HTTP '+width);
assert(x.images.length===7&&y.images.length===7&&y.images.every(z=>z.ok),'all 7 images '+width+' '+JSON.stringify(y.images.filter(z=>!z.ok)));
assert(x.faq===5&&y.faq===5,'5 FAQ '+width);
assert(JSON.stringify(x.LINE)===JSON.stringify(y.LINE)&&y.LINE.length===8,'8 LINE unchanged '+width);
assert(JSON.stringify(x.tel)===JSON.stringify(y.tel)&&y.tel.length===3,'3 phone unchanged '+width);
assert(JSON.stringify(x.reserve)===JSON.stringify(y.reserve),'reserve unchanged '+width);
assert(y.title.includes('浦添市のご家庭へ')&&y.hero.includes('通常分解か完全分解か迷ったら'),'FV '+width);
assert(y.firstHeight<=y.firstLine+2,'H1 line wrap '+width+' '+JSON.stringify({firstHeight:y.firstHeight,firstLine:y.firstLine}));
assert(y.gridItems===5&&y.cols===(width>720?2:1),'grid five conditions '+width+' '+y.cols);
assert(y.quote===1&&y.source&&y.text.includes('匿名カズさん・2026年4月22日'),'verified testimonial '+width);
assert(y.text.includes('出張費0円')&&y.text.includes('9,000円')&&y.text.includes('15,000円')&&y.text.includes('16,000円'),'price preserved '+width);
assert(y.tracking&&y.schema===2,'GA4/schema preserved '+width);
assert(y.scroll<=width&&!y.overflow.length&&!y.errors.length&&!y.bad.length,'layout '+width+' '+JSON.stringify({overflow:y.overflow,bad:y.bad,errors:y.errors}));
results.push({width,http:y.http,images:y.images.length,faq:y.faq,LINE:y.LINE.length,phone:y.tel.length,reserve:y.reserve.length,areas:y.gridItems,cols:y.cols,review:y.quote,overflow:0,errors:0,pass:true});}
console.log('URASOE_PREVIEW_PASS '+JSON.stringify(results));fs.writeFileSync(path.join(out,'report.json'),JSON.stringify(results,null,2));
}finally{if(b)await b.close();if(oldS)await new Promise(r=>oldS.close(r));if(newS)await new Promise(r=>newS.close(r))}})().catch(e=>{console.error('URASOE_PREVIEW_FAIL',e);process.exit(1)});